function Build-Hub($hubSlug, $hubTitle, $metaDesc, $eyebrow, $h1Line1, $h1Em, $lead, $tags, $hubLabel, $gridClass, $sectionLabel, $sectionH3, $sectionP, $locations, $navActive) {
  $hubSrc = Join-Path $root 'ai-industries.html'
  $hub = [System.IO.File]::ReadAllText($hubSrc, $utf8)
  $hub = $hub.Replace('ai-industries.html', $hubSlug)
  $hub = $hub.Replace('AI Solutions by Industry | Sector-Specific AI | Acesoft', $hubTitle)
  $hub = $hub.Replace('Industry-specific AI solutions for healthcare, finance, retail, logistics, and more. Acesoft builds secure, production-ready AI for your sector in Canada and the USA.', $metaDesc)
  $hub = $hub.Replace('og:title" content="AI Solutions by Industry | Acesoft Canada"', ('og:title" content="' + $hubTitle + '"'))
  $hub = $hub.Replace('twitter:title" content="AI Solutions by Industry | Acesoft Canada"', ('twitter:title" content="' + $hubTitle + '"'))
  $hub = $hub.Replace('AI Solutions by Industry', $eyebrow)
  $hub = $hub.Replace('Industry-Specific AI<br>', ($h1Line1 + '<br>'))
  $hub = $hub.Replace('<em>Built for Your Sector</em>', ('<em>' + $h1Em + '</em>'))
  $hub = $hub.Replace('From healthcare and finance to retail and manufacturing-Acesoft delivers AI that respects your regulations, data, and operating model.', $lead)
  $hub = $hub.Replace('id="aiIndustriesHub"', ('id="' + $hubSlug.Replace('.html','') + 'Hub"'))
  $hub = $hub.Replace('Industries We Serve', $sectionLabel)
  $hub = $hub.Replace('Explore AI Solutions by Industry', $sectionH3)
  $hub = $hub.Replace('Each industry has a dedicated page with use cases, deliverables, and how Acesoft can help your team in Canada and beyond.', $sectionP)
  $hub = $hub.Replace('seo-service-grid seo-service-grid--industries', ('seo-service-grid ' + $gridClass))
  $hub = $hub.Replace('View industry', 'View location')
  $hubCards = ($locations | ForEach-Object {
    "            <a href=`"$($_.slug).html`" class=`"seo-service-card`"><span class=`"seo-service-card-icon`"><i class=`"fa $($_.icon)`"></i></span><h4>$($_.title)</h4><p>$($_.hub)</p><span class=`"seo-service-card-link`">View location</span></a>"
  }) -join "`n"
  $hub = [regex]::Replace($hub, '(?s)<div class="seo-service-grid[^"]*">[\s\S]*?</div>\s*</motion>\s*</motion>', "<div class=`"seo-service-grid $gridClass`">`n$hubCards`n          </div>", 1)
  $hub = [regex]::Replace($hub, '(?s)<div class="seo-service-grid[^"]*">[\s\S]*?</motion>\s*</motion>', "<div class=`"seo-service-grid $gridClass`">`n$hubCards`n          </div>", 1)
  $hub = [regex]::Replace($hub, '(?s)<div class="seo-service-grid[^"]*">[\s\S]*?</motion>\s*</div>\s*</div>', "<div class=`"seo-service-grid $gridClass`">`n$hubCards`n          </motion>", 1)
  $hub = [regex]::Replace($hub, '(?s)<div class="seo-service-grid[^"]*">[\s\S]*?</div>\s*</div>', "<div class=`"seo-service-grid $gridClass`">`n$hubCards`n          </div>", 1)
  if ($navActive -eq 'development') {
    $hub = $hub.Replace('<li><a href="ai-industries.html" class="acesoft-nav-current-link">Industries</a></li>', '<li><a href="ai-industries.html">Industries</a></li>')
    $hub = $hub.Replace('<li><a href="ai-development-services.html">AI Development</a></li>', '<li><a href="ai-development-services.html" class="acesoft-nav-current-link">AI Development</a></li>')
  }
  [System.IO.File]::WriteAllText((Join-Path $root $hubSlug), $hub, $utf8)
  Write-Host "Created $hubSlug"
}

Build-Hub 'ai-development-canada.html' 'AI Development Canada | AI Consultants & Developers | Acesoft' 'AI development and consulting across Canada. Explore city-specific AI consultant pages for Toronto, Vancouver, Montreal, London ON, and more.' 'AI Development Canada' 'AI Development' 'Across Canada' 'Canadian-led AI engineering for enterprises and startups-city-specific consultants, secure delivery, and production MLOps from Acesoft.' @('Toronto','London ON','Vancouver','Montreal','Canada-wide') 'Locations' 'seo-service-grid--locations' 'Cities We Serve' 'AI Consultants &amp; Development by City' 'Find AI consultants and development support in major Canadian markets-each page covers local delivery, use cases, and how Acesoft can help.' $canada 'development'

Build-Hub 'ai-development-usa.html' 'AI Development USA | AI Consultants & Developers | Acesoft' 'AI development and consulting across the United States. City pages for New York, San Francisco, Chicago, Boston, Austin, and more.' 'AI Development USA' 'AI Development' 'Across the USA' 'US-friendly collaboration with senior AI engineers-LLM products, automation, and enterprise programs delivered by Acesoft.' @('New York','San Francisco','Chicago','Boston','US-wide') 'Locations' 'seo-service-grid--locations' 'Cities We Serve' 'AI Consultants &amp; Development by City' 'Explore AI consultant and development pages for major US metros-local context, delivery models, and engagement options.' $usa 'development'

$template = [System.IO.File]::ReadAllText((Join-Path $root 'custom-ai-development-services.html'), $utf8)
foreach ($p in ($canada + $usa)) {
  $page = Build-LocationPage $p $template
  [System.IO.File]::WriteAllText((Join-Path $root ($p.slug + '.html')), $page, $utf8)
  Write-Host "Created $($p.slug).html"
}

$sitemapPath = Join-Path $root 'sitemap.xml'
$sitemap = [System.IO.File]::ReadAllText($sitemapPath, $utf8)
if ($sitemap -notmatch 'ai-development-canada.html') {
  $insert = "  <url>`n    <loc>https://www.aidevelopers.ca/ai-development-canada.html</loc>`n  </url>`n  <url>`n    <loc>https://www.aidevelopers.ca/ai-development-usa.html</loc>`n  </url>`n"
  foreach ($p in ($canada + $usa)) {
    $insert += "  <url>`n    <loc>https://www.aidevelopers.ca/$($p.slug).html</loc>`n  </url>`n"
  }
  $sitemap = $sitemap.Replace('</urlset>', ($insert + '</urlset>'))
  [System.IO.File]::WriteAllText($sitemapPath, $sitemap, $utf8)
  Write-Host 'Updated sitemap.xml'
}

Write-Host 'Location setup complete'
